Rule.Source:
import java.io.InputStream;
import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.Iterator;
import java.util.List;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

import sailpoint.object.Custom;
import sailpoint.object.Filter;
import sailpoint.object.JasperResult;
import sailpoint.object.PersistedFile;
import sailpoint.object.QueryOptions;
import sailpoint.object.TaskResult;
import sailpoint.persistence.PersistedFileInputStream;
import sailpoint.tools.GeneralException;
import sailpoint.tools.Util;

Log postLog = LogFactory.getLog("rule.ReportResultPOST");

final String CONFIG_OBJECT_NAME = "Report POST Configuration";
final String CSV_CONTENT_TYPE   = "text/csv";
final int    BUFFER_SIZE        = 8192;

// ------------------------------------------------------------------
// 1. Load configuration
// ------------------------------------------------------------------
Custom config = context.getObjectByName(Custom.class, CONFIG_OBJECT_NAME);
if (config == null) {
  throw new GeneralException("Report Result POST: Custom object '" + CONFIG_OBJECT_NAME + "' not found. Import Custom-Report-POST-Configuration.xml and set its values.");
}

String targetUrl = Util.trimnull((String) config.get("targetUrl"));
String token     = Util.trimnull((String) config.get("bearerToken"));
if (targetUrl == null) {
  throw new GeneralException("Report Result POST: 'targetUrl' is not set in '" + CONFIG_OBJECT_NAME + "'.");
}
if (token == null) {
  throw new GeneralException("Report Result POST: 'bearerToken' is not set in '" + CONFIG_OBJECT_NAME + "'.");
}
// Tokens should be stored encrypted (see README); decrypt() passes
// plaintext through unchanged, so both forms work.
token = context.decrypt(token);

int connectTimeout = Util.atoi(Util.otos(config.get("connectTimeoutMs")));
if (connectTimeout <= 0) connectTimeout = 30000;
int readTimeout = Util.atoi(Util.otos(config.get("readTimeoutMs")));
if (readTimeout <= 0) readTimeout = 300000;

// ------------------------------------------------------------------
// 2. Resolve the TaskResult
// ------------------------------------------------------------------
TaskResult result = taskResult;
if (result == null) {
  String reportName = Util.trimnull((String) config.get("reportName"));
  if (reportName == null) {
    throw new GeneralException("Report Result POST: no taskResult argument and no 'reportName' configured in '" + CONFIG_OBJECT_NAME + "'.");
  }
  QueryOptions qo = new QueryOptions();
  qo.addFilter(Filter.eq("definition.name", reportName));
  qo.addFilter(Filter.notnull("completed"));
  qo.addOrdering("completed", false);
  qo.setResultLimit(1);
  List results = context.getObjects(TaskResult.class, qo);
  if (Util.isEmpty(results)) {
    throw new GeneralException("Report Result POST: no completed TaskResult found for report '" + reportName + "'.");
  }
  result = (TaskResult) results.get(0);
}

String reportLabel = result.getName();
postLog.info("Report Result POST: processing TaskResult '" + reportLabel + "' (" + result.getId() + ")");

// ------------------------------------------------------------------
// 3. Find the CSV PersistedFile on the JasperResult
// ------------------------------------------------------------------
JasperResult jasper = result.getReport();
if (jasper == null) {
  throw new GeneralException("Report Result POST: TaskResult '" + reportLabel + "' has no report result attached. Is it a report task?");
}

PersistedFile csvFile = null;
List files = jasper.getFiles();
if (files != null) {
  for (Iterator it = files.iterator(); it.hasNext(); ) {
    PersistedFile pf = (PersistedFile) it.next();
    if (pf != null && CSV_CONTENT_TYPE.equalsIgnoreCase(pf.getContentType())) {
      csvFile = pf;
      break;
    }
  }
}
if (csvFile == null) {
  throw new GeneralException("Report Result POST: no CSV file on TaskResult '" + reportLabel + "'. Enable 'Save Report as CSV' in the report's Standard Properties.");
}

// ------------------------------------------------------------------
// 4. Stream the CSV to the target URL
// ------------------------------------------------------------------
// The report definition name identifies the report type to the receiver.
String reportTypeName = (result.getDefinition() != null) ? result.getDefinition().getName() : reportLabel;

HttpURLConnection conn = null;
InputStream in = null;
OutputStream out = null;
long bytesSent = 0L;
int status;
String responseSnippet = "";

try {
  conn = (HttpURLConnection) new URL(targetUrl).openConnection();
  conn.setRequestMethod("POST");
  conn.setDoOutput(true);
  // Chunked streaming: the file is never fully held in memory and no
  // Content-Length needs to be precomputed.
  conn.setChunkedStreamingMode(BUFFER_SIZE);
  conn.setConnectTimeout(connectTimeout);
  conn.setReadTimeout(readTimeout);
  conn.setRequestProperty("Authorization", "Bearer " + token);
  conn.setRequestProperty("Content-Type", CSV_CONTENT_TYPE);
  conn.setRequestProperty("X-Report-Name", reportTypeName);

  in = new PersistedFileInputStream(context, csvFile);
  out = conn.getOutputStream();
  byte[] buffer = new byte[BUFFER_SIZE];
  int read;
  while ((read = in.read(buffer)) != -1) {
    out.write(buffer, 0, read);
    bytesSent += read;
  }
  out.flush();

  status = conn.getResponseCode();
  InputStream respStream = (status >= 200 && status < 300) ? conn.getInputStream() : conn.getErrorStream();
  if (respStream != null) {
    try {
      byte[] respBuf = new byte[512];
      int respRead = respStream.read(respBuf);
      if (respRead > 0) {
        responseSnippet = new String(respBuf, 0, respRead, "UTF-8");
      }
    } finally {
      respStream.close();
    }
  }
} finally {
  if (in != null) { try { in.close(); } catch (Exception e) { /* best effort */ } }
  if (out != null) { try { out.close(); } catch (Exception e) { /* best effort */ } }
  if (conn != null) { conn.disconnect(); }
}

if (status < 200 || status >= 300) {
  String msg = "Report Result POST: POST of '" + csvFile.getName() + "' (" + bytesSent + " bytes) failed with HTTP " + status + ": " + responseSnippet;
  postLog.error(msg);
  throw new GeneralException(msg);
}

String summary = "Report Result POST: sent '" + csvFile.getName() + "' (" + bytesSent + " bytes) for report '" + reportTypeName + "', HTTP " + status;
postLog.info(summary);
return summary;
